#pragma once

// Terrain/water mip-chain policy, shared by the software rasterisers
// (SoftTerrain.cpp, SoftWater.cpp) and the GL texture array
// (GLTerrain.cpp :: EnsureTerrainTextureArray).
//
// Pure header -- no windows.h, no GL, no engine globals -- so the selection
// rules stay unit-testable without a renderer (tests/test_terrain_mip.cpp).
//
// Chain layout, generated by Loaders/ModelLoader.cpp :: LoadTexture:
//   level 0 = DataA 128x128    level 1 = DataB 64x64
//   level 2 = DataC 32x32      level 3 = DataD 16x16

// Levels generated by the loader and allocated by the GL array.
inline constexpr int kTerrainMipLevelCount = 4;

// The software rasterisers only ever sampled A/B/C; DataD is reserved for the
// tactical map thumbnail (Loaders/ModelLoader.cpp :: GenerateMapImage).
inline constexpr int kTerrainRasterMipLevels = 3;

// Software rasteriser: the texel size a level-0 (128x128) texture is minified
// to at `distance` world units in a `cameraWidth`-pixel viewport. This is the
// legacy estimator (CameraW * 4 * 128 / zs) moved behind a guard.
//
// `distance` is clamped to >= 1. The tile the camera stands in can have its
// centre arbitrarily close to the eye, and the legacy expression divided by
// it unguarded -- an integer divide-by-zero raises #DE and kills the frame.
// The result is then clamped to >= 1 because it counts on-screen texels: it
// must never be 0 or negative, whatever the viewport. Both clamps only affect
// degenerate input, and either way such a tile selects level 0.
inline int ComputeMipTexelSize(int cameraWidth, int distance)
{
	if (cameraWidth < 1) cameraWidth = 1;
	if (distance < 1) distance = 1;
	const int texelSize = cameraWidth * 4 * 128 / distance;
	return texelSize < 1 ? 1 : texelSize;
}

// Level choice for the software rasterisers, preserving the legacy three-way
// thresholds exactly: >=128 -> DataA, >=64 -> DataB, otherwise DataC.
inline int SelectRasterMipLevel(int texelSize)
{
	if (texelSize >= 128) return 0;
	if (texelSize >= 64) return 1;
	return 2;
}

// Highest level the GL terrain/water sampler may select, as a
// config.cfg "terrain_mip_level" value.
//
// Default 3 exposes the whole chain. Levels 2-3 (DataC 32x32, DataD 16x16)
// were always uploaded by the loader, so raising the cap costs no memory; the
// owner reviewed the four-level result and accepted it on 2026-09-21. The
// stock D3D/3DFX renderers only ever sampled DataA and DataB, which is why
// the GL port inherited a cap of 1 when the 2x2 geometry-LOD system was
// removed (e4cdd32) -- 1 is no longer the interesting default. 0 disables
// mip filtering. See architecture/terrain-rendering.md.
inline constexpr int kTerrainMaxMipDefault = 3;
inline constexpr int kTerrainMaxMipMin = 0;
inline constexpr int kTerrainMaxMipMax = kTerrainMipLevelCount - 1;

// Defence in depth for a hand-edited config.cfg. LoadConfig rejects
// out-of-range values through ParseConfigInt, so this only runs if a caller
// bypasses it; clamp to the valid span rather than silently reverting.
inline int ClampTerrainMaxMipLevel(int requestedLevel)
{
	if (requestedLevel < kTerrainMaxMipMin) return kTerrainMaxMipMin;
	if (requestedLevel > kTerrainMaxMipMax) return kTerrainMaxMipMax;
	return requestedLevel;
}
